import { uniqueStrings } from './unique_changed.mjs';
import assert from 'node:assert';

// Basic dedup preserving first occurrence and order
assert.deepStrictEqual(
  uniqueStrings(['a', 'b', 'a', 'c', 'b']),
  ['a', 'b', 'c']
);

// ASCII case differences ignored, original spelling preserved
assert.deepStrictEqual(
  uniqueStrings(['Hello', 'hello', 'HELLO', 'World', 'world']),
  ['Hello', 'World']
);

// Whitespace not trimmed
assert.deepStrictEqual(
  uniqueStrings([' a ', 'a', ' a ', 'a']),
  [' a ', 'a']
);

// Empty input
assert.deepStrictEqual(uniqueStrings([]), []);

// Input not mutated
const input = ['x', 'X', 'y', 'x'];
const snapshot = [...input];
uniqueStrings(input);
assert.deepStrictEqual(input, snapshot);

// Mixed case with distinct keys
assert.deepStrictEqual(
  uniqueStrings(['Apple', 'apple', 'Banana', 'banana', 'APPLE']),
  ['Apple', 'Banana']
);

console.log('All checks passed.');
"

